std::string str_key = key.ToString();
  std::string str_value = value.ToString();

  // Calculate shared prefix length
  size_t shared = 0;
  if (!last_key->empty()) {
    shared = std::min(static_cast<size_t>(key.size()), static_cast<size_t>(last_key->size()));
    for (size_t i = 0; i < shared && i < key.size() && i < last_key->size(); i++) {
      if (key[i] != (*last_key)[i]) {
        shared = i;
        break;
      }
    }
  }

  // Calculate non-shared length
  size_t non_shared = key.size() - shared;

  // Add entry to buffer
  // Entry format: [shared_len, non_shared_len, value_len, shared_data, non_shared_data, value_data]
  PutVarint32(buffer, shared);
  PutVarint32(buffer, non_shared);
  PutVarint32(buffer, value.size());
  buffer->append(key.data() + shared, non_shared);
  buffer->append(value.data(), value.size());

  // Update last_key
  *last_key = str_key;

  // Handle restart points
  (*counter)++;
  if (*counter % restart_interval == 0) {
    restarts->push_back(buffer->size());
  }
// END_CODE

